#ifndef __FORM_H
#define __FORM_H

#include <ufc.h>

#include <dolfin/common/Array.h>
#include "DofMapSet.h"
#include <dolfin/function/Function.h>
#include <dolfin/mesh/MeshFunction.h>

#include <string>

namespace dolfin
{

/// Base class for UFC code generated by FFC for DOLFIN with option -l

class Form
{
public:

  /// Constructor
  Form();

  /// Destructor
  virtual ~Form();

  /// Return UFC form
  virtual const ufc::form& form() const = 0;

  /// Return array of coefficients
  virtual const Array<Function*>& coefficients() const = 0;

  /// Return number of argument associated with the given name
  virtual uint coefficient_number(const std::string& name) const;

  /// Return name of argument associated with the given number
  virtual std::string coefficient_name(dolfin::uint i) const;

  /// Create degree of freedom maps
  void updateDofMaps(Mesh& mesh) const;

  /// Return DofMapSet
  DofMapSet& dofMaps() const;

private:

  // Degree of freedom maps
  mutable DofMapSet * dof_map_set_;

};

}

#endif
